import{z as i,x as m,o,c as n,q as t,j as B,D as e,d as r,s as A,S as s,b as E}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"过度提交","description":"","frontmatter":{"title":"过度提交","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/overcommit.md","filePath":"cs/overcommit.md","lastUpdated":1791063341000}'),d={name:"cs/overcommit.md"};function p(c,a,C,O,h,f){const l=m("Mermaid");return o(),n("div",null,[a[2]||(a[2]=t('<h1 id="过度提交" tabindex="-1">过度提交 <a class="header-anchor" href="#过度提交" aria-label="Permalink to &quot;过度提交&quot;">​</a></h1><div class="epigraph"><p>内核可以允许虚存承诺之和大于 RAM 加 swap：多数页从未被写满；一旦同时触碰，OOM 才出现。</p><footer>—— 据 Silberschatz 对分配与提交的区分；Linux overcommit 策略的整理</footer></div><p><a href="/cs/oom-killer">上一课</a>在真正缺帧时杀人。<a href="/cs/brk-heap">brk 与堆</a>升高水位并不立刻占帧。<a href="/cs/demand-paging">按需调页</a>把占帧推迟到访问。缺口是<strong>承诺会计</strong>：<code>malloc</code>/<code>mmap</code> 成功只表示 VMA 记下了，是否计入「保证能配到的帧」，由过度提交策略决定。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>严格提交：每次扩大匿名区都扣减「剩余可保证页」（RAM+swap−已提交）。稀疏堆、巨大稀疏数组会立刻失败，尽管工作集很小。宽松提交：几乎总成功，把风险推到缺页与 OOM。启发式：看空闲与可回收文件页，允许一定倍率。缺口不是 CLOCK，而是用户接口何时返回 ENOMEM，何时把失败藏到稍后的故障。</p><p><span class="marginnote">数字实例：机器 16 GB 内存加 8 GB swap，宽松策略下进程 A、B 各 malloc 12 GB 也能同时成功——承诺合计 24 GB 超过物理总量；只要两者实际各只写 2 GB 就相安无事，谁先写满谁触发清算。</span></p><p><span class="marginnote">常见误区：初学者容易把 malloc 返回非 NULL 当「内存已到手」。宽松策略下它只表示记账通过；真正的考验在第一次写每一页的时刻——分配成功与物理到位是两件事。</span></p><p>本课不把 <code>vm.overcommit_memory</code> 的三个整数当唯一真理，只作策略对照。</p><p><span class="marginnote">提交的是匿名与私有写潜力；共享只读文件通常不按「每映射一份物理页」记账。fork 的 COW 会把承诺翻倍——下一课用写时复制推迟真拷贝，但会计可能已经加倍。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>内核维护 committed 计数。策略 A：超过 RAM+swap 则 <code>mmap</code>/<code>brk</code> 失败。策略 B：允许超过，OOM 兜底。策略 C：按空闲估计。用户要「真保证」可用 mlock 或关闭过度提交，代价是必须现在就有帧。与抖动对照：过度提交提高多道的虚上限，使 ΣW 更容易在运行期爆炸。</p>',11)),(o(),B(s,null,{default:e(()=>[A(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22brk%2Fmmap%22%5D%20--%3E%20ACC%5B%22%E6%8F%90%E4%BA%A4%E4%BC%9A%E8%AE%A1%22%5D%0A%20%20ACC%20--%3E%7C%E4%B8%A5%E6%A0%BC%E4%B8%94%E6%BB%A1%7C%20ENOMEM%5B%22%E7%8E%B0%E5%9C%A8%E5%A4%B1%E8%B4%A5%22%5D%0A%20%20ACC%20--%3E%7C%E5%AE%BD%E6%9D%BE%7C%20OK%5B%22VMA%20%E6%88%90%E5%8A%9F%22%5D%0A%20%20OK%20--%3E%20LATER%5B%22%E8%A7%A6%E7%A2%B0%E6%97%B6%E7%BC%BA%E9%A1%B5%2FOOM%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"过度提交把「虚存接口」和「物理保证」拆开，让稀疏数据结构便宜。它解释了为何 OOM 发生在运行很久之后，而不是 malloc 那一行。不要把这写成攻击教程；只说明会计与按需的组合会产生延迟失败。文件页可回收，常不按一对一计入匿名承诺。",-1)),a[5]||(a[5]=E("p",null,"失败被推迟到什么时刻：malloc 那一行永远成功，真帧按「写到哪页给哪页」逐页发放；总量耗尽的那一次写，才是错误浮现的位置。这就是「延迟失败」——出错点与出错行隔了整个运行期。",-1)),(o(),B(s,null,{default:e(()=>[A(l,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22malloc%2012%20GB%EF%BC%8C%E5%AE%BD%E6%9D%BE%E7%AD%96%E7%95%A5%22%5D%20--%3E%20OK%5B%22VMA%20%E8%AE%B0%E8%B4%A6%E6%88%90%E5%8A%9F%EF%BC%8C%E7%AB%8B%E5%88%BB%E8%BF%94%E5%9B%9E%22%5D%0A%20%20OK%20--%3E%20TOUCH%5B%22%E7%A8%8B%E5%BA%8F%E9%80%90%E9%A1%B5%E5%86%99%E5%85%A5%22%5D%0A%20%20TOUCH%20--%3E%20PF%5B%22%E6%AF%8F%E6%AC%A1%E9%A6%96%E5%86%99%E8%A7%A6%E5%8F%91%E7%BC%BA%E9%A1%B5%EF%BC%8C%E9%A2%86%E4%B8%80%E4%B8%AA%E7%9C%9F%E5%B8%A7%22%5D%0A%20%20PF%20--%3E%20Q%7B%22%E5%B8%A7%E8%BF%98%E9%A2%86%E5%BE%97%E5%88%B0%E5%90%97%3F%22%7D%0A%20%20Q%20--%3E%7C%22%E8%83%BD%22%7C%20MORE%5B%22%E7%BB%A7%E7%BB%AD%E8%B7%91%EF%BC%8C%E5%A4%B1%E8%B4%A5%E7%BB%A7%E7%BB%AD%E6%8E%A8%E8%BF%9F%22%5D%0A%20%20Q%20--%3E%7C%22%E4%B8%8D%E8%83%BD%22%7C%20OOM%5B%22%E5%86%85%E6%A0%B8%E6%B8%85%E7%AE%97%EF%BC%9AOOM%20killer%20%E9%80%89%E7%89%BA%E7%89%B2%E8%80%85%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<p><span class="marginnote">直觉类比：过度提交像餐厅超卖订位——按「不会人人都到齐」多接订单，绝大多数晚上相安无事；真满员那晚就得请某桌离开，这就是 OOM killer。</span></p><p><a href="/cs/paging-vm">分页</a> 仍只在缺页时要帧；会计是 OS 策略层。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 memcg 的 per-group 提交限额全文。不保证用户态能可移植地查询「还剩多少保证」。下一课 <code>fork</code> 若立刻复制全部页，再严格的会计也会在创建进程时爆掉——于是写时复制把复制推迟，同时把承诺问题变得更尖锐。</p><p>后课默认：VMA 可以大于物理。<code>fork</code> 的副本若立刻占两倍帧则不可接受，下一课写时复制。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>提交会计决定「现在失败」还是「以后 OOM」。</li><li>按需加上宽松提交，使稀疏堆可行。</li><li>fork 的复制代价是 COW 的缺口。</li><li>出处：Silberschatz et al., <em>OSC</em>；Linux overcommit 文档；Tanenbaum <em>MOS</em>。</li></ul>',7))])}const M=i(d,[["render",p]]);export{D as __pageData,M as default};
